constexpr int inf = 0x3f3f3f3f;
constexpr int maxn = 510;
int mod;

int factorial[maxn], inv_factorial[maxn], inv[maxn];

void precompute() {
	factorial[0] = factorial[1] = inv[1] = inv_factorial[0] = inv_factorial[1] = 1;
	for(int i = 2; i < maxn; i++) {
		factorial[i] = (int)(1ll * factorial[i-1] * i % mod);
		inv[i] = mod - (int)(1ll * (mod/i) * inv[mod%i] % mod);
		inv_factorial[i] = (int)(1ll * inv_factorial[i-1] * inv[i] % mod);
	}
}

inline int choose(int a, int b) {
	return (int)(1ll * factorial[a] * (1ll * inv_factorial[b] * inv_factorial[a-b] % mod) % mod);
}

inline ll sum_pairs(int x) { return 1ll * x * (x+1) / 2; }

int f[maxn], c[maxn], dpA[maxn][maxn], dpB[maxn][maxn];

int main() {
	int n, m; scanf("%d %d %d", &n, &m, &mod);
	precompute();
	f[0] = 1;
	for(int i = 1; i <= m; i++) {
		for(int j = 0; j < i; j++) {
			f[i] += (int)((1ll * choose(i-1, j) * f[j] % mod) * f[i-1-j] % mod);
			if(f[i] >= mod) f[i] -= mod;
			c[i] += (int)((1ll * (i+1) * choose(i-1, j) % mod) *
				((1ll * f[j] * c[i-1-j] % mod) + (1ll * f[i-1-j] * c[j] % mod) % mod) % mod);
			if(c[i] >= mod) c[i] -= mod;
			c[i] += (int)((1ll * choose(i-1, j) * (sum_pairs(j) + sum_pairs(i-1-j)) % mod) *
				(1ll * f[j] * f[i-1-j] % mod) % mod);
			if(c[i] >= mod) c[i] -= mod;
		}
		f[i] = (int)(1ll * f[i] * (i+1) % mod);
	}
	memset(dpA, 0, sizeof(dpA));
	memset(dpB, 0, sizeof(dpB));
	dpA[0][0] = 1;
	for(int k = 1; k <= n; k++) {
		dpA[k][0] = 1;
		for(int i = 1; i <= min(m, k); i++) {
			dpA[k][i] = dpA[k-1][i];
			dpB[k][i] = dpB[k-1][i];
			for(int j = 1; j <= i; j++) {
				dpA[k][i] += (int)((1ll * f[j] * dpA[max(k-j-1, 0)][i-j] % mod) * choose(i, j) % mod);
				if(dpA[k][i] >= mod) dpA[k][i] -= mod;

				dpB[k][i] += (int)((1ll * c[j] * dpA[max(k-j-1, 0)][i-j] % mod) * choose(i, j) % mod);
				if(dpB[k][i] >= mod) dpB[k][i] -= mod;
				dpB[k][i] += (int)((1ll * f[j] * dpB[max(k-j-1, 0)][i-j] % mod) * choose(i, j) % mod);
				if(dpB[k][i] >= mod) dpB[k][i] -= mod;
			}
		}
	}
	printf("%d\n", dpB[n][m]);
